    # Fill with blue (1)
    for y in range(3, 7):
        for x in range(3, 7):
            parsed_input[y][x] = 1

    return parsed_input

def guess3(task_id: str) -> list:
    """
    Pattern: Fill interior such that it's half orange, half blue.
    Blue goes left half, orange goes right half.
    """
    parsed_input = [[0]*10 for _ in range(10)]

    # Hollow rectangle
    for x in range(2, 8):
        parsed_input[2][x] = 5
        parsed_input[7][x] = 5
    for y in range(3, 7):
        parsed_input[y][2] = 5
        parsed_input[y][7] = 5

    # Fill interior
